"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[56530],{3366:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ActivePerksGuiController","desc":"Binds the Studio-authored `StarterGui.ActivePerksGui` (Ocean Sunset rebuild, see\\n`roblox-gui-prototypes/2026-10-27-active-perks-gui-prototype.html`): a read-only\\nview of the perks buffing the player right now. Each tab lists the active\\npermanent perks first (`PerkClient`), then the run\'s shop perks: Personal = your\\n`ActiveRun.Personal` minus ended clocks; Party = every party shop perk live in\\nthe run (`PartyPerkBuffs.<Id>HolderId ~= 0`). A Personal perk is active at the\\nplayer\'s own level > 0; a Party perk at the server-wide max, and `OwnerBox`\\nnames the player holding it.\\n\\nEach row is styled by its type (no rarity config): PERMANENT, THIS RUN\\n(Consumable), TIMED (Expiring) or SUPER RARE (`BoxOnly`, wins over Kind). Opens\\nfrom a TopbarPlus icon (toggle key O). It is the Game Instance\'s only perk GUI:\\nperk changes are Lobby-only (`PerkMenuGuiController`). Size follows the screen\\nthrough `MainContainer.UIScale`: wide = min(W/1920, H/1022); below 0.68 the\\ncompact layout (authored at 844x332, scale clamped to [0.75, 1.5]) applies.","realm":["Client"],"source":{"line":22,"path":"src/StarterPlayer/StarterPlayerScripts/ActivePerksGuiController.client.luau"}}')}}]);